import json

# Let's check the JSON file more thoroughly for any exchange rate data
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# The JSON structure seems complex, let's explore it
print("Type:", type(data))

if isinstance(data, dict):
    print("Keys:", list(data.keys())[:20])
    # Look for any exchange rate or currency related fields
    def find_keys(obj, path=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_path = f"{path}.{k}" if path else k
                if 'exchange' in k.lower() or 'yen' in k.lower() or 'jpy' in k.lower() or 'currency' in k.lower():
                    print(f"Found: {new_path}")
                find_keys(v, new_path)
        elif isinstance(obj, list) and len(obj) > 0:
            find_keys(obj[0], f"{path}[0]")

    find_keys(data)
elif isinstance(data, list):
    print("Length:", len(data))
    if len(data) > 0:
        print("First element type:", type(data[0]))
